mapper.sql:
left join ( select dedup_archive.P_Id as project_id, sfa2.File_MD5_Code as file_md5, max(
) as max_key from Archive_File af2 left join Archive dedup_archive on dedup_archive.Ap_Id = af2.Ap_Id inner join SYS_FileAnnex sfa2 on sfa2.file_id = af2.Af_Annex_Id where sfa2.File_MD5_Code is not null
and dedup_archive.P_Id = #{${projectIdParameter}}
group by dedup_archive.P_Id, sfa2.File_MD5_Code ) latest_md5 on sfa.File_MD5_Code = latest_md5.file_md5 and (${archiveAlias}.P_Id = latest_md5.project_id or (${archiveAlias}.P_Id is null and latest_md5.project_id is null)) and
= latest_md5.max_key

(
select ranked.*
from (
select project_files.*,
max(project_files.archive_rank_key) over (
partition by project_files.archive_project_id, project_files.archive_md5
) as archive_max_key
from (
select af.*,
source_archive.P_Id as archive_project_id,
source_annex.File_MD5_Code as archive_md5,

    

as archive_rank_key
from Archive_File af
left join Archive source_archive on source_archive.Ap_Id = af.Ap_Id
left join SYS_FileAnnex source_annex on source_annex.file_id = af.Af_Annex_Id

    
        source_archive.P_Id = #{params.pId}
    

) project_files
) ranked
where ranked.archive_md5 is null or ranked.archive_rank_key = ranked.archive_max_key
) mn

mapper.select:
select dir.Ad_Id as adId, dir.Ad_Parent_Id as parentId, case when exists ( select 1 from Archive_Directory_Group adg inner join SYS_Department dep on dep.D_Id = adg.Adg_Group_Id inner join SYS_Position pos on pos.D_Id = dep.D_Id inner join SYS_Position_User pu on pu.P_Id = pos.P_Id inner join SYS_User usr on usr.U_Id = pu.U_Id where adg.Ad_Id = dir.Ad_Id and adg.Adg_Type in ('01', '02') and not exists ( select 1 from SYS_User grantee where grantee.U_Id = adg.Adg_Group_Id ) and usr.U_Id = #{user.id}
and adg.Te_Id = #{user.teId} and usr.Te_Id = #{user.teId}
) then 2
when dir.Te_Id is null or dir.Te_Id != #{user.teId} then 1
when exists ( select 1 from Archive_Directory_Group local_config where local_config.Ad_Id = dir.Ad_Id
and local_config.Te_Id = #{user.teId}
) then 1 else 0 end as accessState from Archive_Directory dir

