inner join SYS_Department shared_department on shared_department.D_Id = reader_position.D_Id
inner join SYS_Position creator_position on creator_position.D_Id = shared_department.D_Id
inner join SYS_Position_User creator_assignment on creator_assignment.P_Id = creator_position.P_Id
inner join SYS_User creator on creator.U_Id = creator_assignment.U_Id
where reader_assignment.U_Id = #{params.wzUser.id}
and creator.U_Id = mn.Af_Create_Uid

    and creator.Te_Id = #{params.wzUser.teId}

)

mapper.select:
select
pro.P_Construction_Start as pConstructionStart, pro.P_Construction_End as pConstructionEnd, pro.P_Id as pId, ad.Ad_Id as adId, ad.Ad_Code as adCode, ad.Ad_Name as adName, ad.Ad_Link as adLink, ap.Ap_Title as apTitle, ap.Ap_Author as apAuthor, ap.Ap_Keyword as apKeyword, ap.Ap_Position as apPosition, ap.Ap_Document_No as apDocumentNo, ap.Ap_Written_Date as apWrittenDate, ap.Ap_Issue_Company as apIssueCompany, ap.Ap_Approval_Date as apApprovalDate, ap.Ap_Receipt_Time as apReceiptTime, ap.Ap_State as apState, sfa.File_Input_Version as fileInputVersion, sfa.file_create_u_id as fileCreateUid, sfa.file_create_u_name as fileCreateUname, st.t_name as tempName, ifnull(c11.C_Name, pro.P_Use_Unit) as pUseUnitName, mn.*
left join sys_file sf2 on sf2.fileid = sfa.File_Entity_Id left join SYS_FileTemplate st on st.t_id = sf2.t_id
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Af_Create_Time desc, ad.Ad_Name desc
